import type { Metadata } from "next";
import ThemeIcon from "./ThemeIcon";
import { PlanCard, PortfolioButton, SectionTag, ServiceCell } from "./DashboardComponents";
import "./mono-portfolio.css";

export const metadata: Metadata = { title: "Mono Portfolio — Mika Arden", description: "An original creative designer portfolio template built with Coordiation." };

const tools = [
  ["widget-4", "Figma", "Interface systems and rapid collaborative prototyping."],
  ["palette", "Webflow", "Expressive editorial websites with dependable structure."],
  ["code", "Code", "Production-minded components and accessible interactions."],
  ["monitor", "Framer", "High-fidelity motion studies and launch-ready pages."],
] as const;

const projects = ["Orbit Finance System", "Sonder Travel Platform", "Kindred Health Service", "Morrow Culture Journal"];

const faqs = [
  ["What happens in the first week?", "We align on audience, business goals, constraints, success signals, and the smallest useful release."],
  ["Can you work with our existing brand?", "Yes. I can extend a mature system or clarify an identity that has grown inconsistent."],
  ["Do you collaborate with developers?", "Always. Design decisions are documented for implementation and reviewed with the people building them."],
  ["Can the scope grow after launch?", "Yes. The system is intentionally structured so new pages and flows can be added without starting over."],
];

const posts = [
  ["blog-team.jpg", "May 29, 2026", "Designing through disagreement without losing momentum"],
  ["blog-design.jpg", "May 21, 2026", "The quiet details that make an interface feel trustworthy"],
  ["blog-wireframe.jpg", "May 12, 2026", "Why clear wireframes lead to braver visual systems"],
];

export default function MonoPortfolioPreview() {
  return <main className="mono-portfolio co-overflow-hidden" id="top">
    <header className="mp-header co-grid co-items-center"><a className="mp-brand co-flex co-items-center" href="#top"><b>M.</b><span>Mika Arden<br /><small>Designer &amp; creative developer</small></span></a><nav className="co-flex co-items-center co-justify-center" aria-label="Portfolio navigation"><a href="#about">About</a><a href="#work">Work</a><a href="#services">Services</a><a href="#pricing">Pricing</a><a href="#contact">Contact</a></nav><a className="mp-header-cta co-flex co-items-center co-justify-between" href="#contact">Let&apos;s talk <ThemeIcon name="arrow-to-top-right" size={18} tone="light" /></a><details className="mp-menu"><summary aria-label="Open navigation"><ThemeIcon name="hamburger-menu" size={22} /></summary><div><a href="#about">About</a><a href="#work">Work</a><a href="#services">Services</a><a href="#pricing">Pricing</a><a href="#contact">Contact</a></div></details></header>

    <section className="mp-hero co-grid co-items-center"><div className="mp-hero-copy"><SectionTag>Available for select projects</SectionTag><h1>Useful brands.<br />Clear digital<br /><em>experiences.</em></h1><p>Strategy, identity, and interface design for teams creating products people can understand, trust, and keep using.</p><div className="mp-actions co-flex co-items-center"><PortfolioButton href="#work">View work</PortfolioButton><a href="#contact">Contact me <ThemeIcon name="arrow-to-top-right" size={14} /></a></div></div><div className="mp-hero-board co-grid"><figure className="co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover" src="/themes/mono-portfolio/hero.jpg" alt="Portrait of Mika Arden, independent designer" /></figure><aside className="mp-location"><ThemeIcon name="map-point" size={17} /><b>Jakarta, Indonesia</b><small>Working worldwide</small></aside><aside className="mp-social"><small>Find me</small><div className="co-flex"><a href="#contact">IG</a><a href="#contact">IN</a><a href="#contact">BE</a></div></aside><aside className="mp-count"><strong>180+</strong><span>Projects shaped</span><small><ThemeIcon name="star" size={13} /> 4.9 average partner rating</small></aside><aside className="mp-skills co-flex co-items-center"><b>Specializing in</b><span>UX/UI</span><span>Brand systems</span><span>Frontend</span></aside></div></section>

    <section className="mp-marquee" aria-label="Services"><div className="co-flex co-items-center co-animate-[mp-marquee_24s_linear_infinite] motion-reduce:co-animate-none">{[0,1].map(set=><span className="co-flex co-items-center" key={set}>UI/UX Design <i/> Web Design <i/> Brand Systems <i/> Frontend <i/> Creative Direction <i/></span>)}</div></section>

    <section className="mp-section mp-about co-grid" id="about"><div className="mp-about-copy"><SectionTag>About me</SectionTag><h2>Curiosity into<br />clear, useful<br />outcomes.</h2><p>I&apos;m Mika, an independent designer who helps growing teams turn complicated ideas into focused identities and digital products. My work lives between structure and personality.</p><PortfolioButton href="#services">Learn more</PortfolioButton></div><figure className="co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover" src="/themes/mono-portfolio/about.jpg" alt="Mika Arden in a studio portrait" /></figure><div className="mp-tools"><b>Tools and practices</b>{tools.map(([icon,title,copy])=><article className="co-grid co-items-center" key={title}><ThemeIcon name={icon} size={23} /><div><h3>{title}</h3><p>{copy}</p></div></article>)}</div></section>

    <section className="mp-section mp-work" id="work"><div className="mp-heading co-flex co-items-end co-justify-between"><div><SectionTag>Selected work</SectionTag><h2>Projects with a<br />point of view.</h2></div><p>From digital services to editorial products, every engagement starts with what people need to understand and do.</p></div><div className="mp-work-grid co-grid"><a className="mp-feature-project co-relative co-overflow-hidden" href="#contact"><img className="co-w-full co-h-full co-object-cover co-transition co-duration-300 co-ease-out" src="/themes/mono-portfolio/project.jpg" alt="Laptop presenting a financial product interface" /><div className="co-absolute"><small>2026 · UX/UI · Design system</small><h3>Orbit Finance Control Room</h3><ThemeIcon name="arrow-to-top-right" size={18} tone="light" /></div></a><div className="mp-project-list">{projects.map((project,index)=><a className="co-flex co-items-center co-justify-between" href="#contact" key={project}><span>{project}</span><small>0{index+1}</small></a>)}<PortfolioButton href="#contact">View more</PortfolioButton></div></div></section>

    <section className="mp-section mp-services" id="services"><div className="mp-heading is-centered co-text-center"><SectionTag centered>Services</SectionTag><h2>Services for<br />modern brands.</h2><p>Choose a focused engagement or combine capabilities around the exact outcome your team needs.</p></div><div className="mp-service-grid co-grid"><ServiceCell number="01" icon="widget-4" title="UX/UI design" copy="Clear product flows, systems, and interfaces that make complex work feel manageable." /><ServiceCell number="02" icon="monitor" title="Web design" copy="Editorial websites with strong hierarchy, deliberate rhythm, and responsive detail." /><ServiceCell number="03" icon="pen-new-square" title="Brand systems" copy="Identity foundations that give every channel a shared, recognizable voice." /><ServiceCell number="04" icon="code" title="Frontend systems" copy="Accessible component thinking that bridges design intent and production reality." /><ServiceCell number="05" icon="lightbulb" title="Creative strategy" copy="Positioning, principles, and priorities that make the next decisions easier." /><ServiceCell number="06" icon="palette" title="Art direction" copy="A coherent image, typography, and motion language for a memorable launch." /></div></section>

    <section className="mp-trust co-grid"><div><SectionTag>Why choose Mono</SectionTag><h2>Clarity.<br />Character.<br />Momentum.</h2></div><div className="mp-trust-points co-grid"><article><span>01</span><ThemeIcon name="widget-4" size={20} tone="lime" /><h3>Modern, minimal systems</h3><p>Enough structure to scale without flattening the brand.</p></article><article><span>02</span><ThemeIcon name="lightbulb" size={20} tone="lime" /><h3>Strategy-led creativity</h3><p>Every expressive choice has a reason and a job to do.</p></article><figure className="co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover" src="/themes/mono-portfolio/workspace.jpg" alt="A bright creative studio workspace" /></figure><article><span>03</span><ThemeIcon name="users-group-rounded" size={20} tone="lime" /><h3>Responsive collaboration</h3><p>Short feedback loops keep the work moving and visible.</p></article><article><span>04</span><ThemeIcon name="eye" size={20} tone="lime" /><h3>Attention to detail</h3><p>The final ten percent receives the same care as the first idea.</p></article></div></section>

    <section className="mp-section mp-pricing" id="pricing"><div className="mp-heading is-centered co-text-center"><SectionTag centered>Pricing</SectionTag><h2>A plan for your<br />next goal.</h2><p>Transparent starting points that can be adjusted around scope, timing, and team.</p></div><div className="mp-plan-grid co-grid"><PlanCard name="Starter" price="$2.4k" /><PlanCard name="Professional" price="$5.8k" featured /><PlanCard name="Partnership" price="$9.6k" /></div></section>

    <section className="mp-section mp-reviews"><div className="mp-heading co-flex co-items-end co-justify-between"><div><SectionTag>Reviews</SectionTag><h2>Good work,<br />built together.</h2></div><p>Direct communication, honest critique, and steady progress from the first conversation to launch.</p></div><div className="mp-review-grid co-grid"><aside><strong>4.9<small>/5</small></strong><p>Rated by partners across product, culture, and public-service teams.</p><div>★★★★★</div><PortfolioButton href="#contact">Start a project</PortfolioButton></aside><blockquote><span>“</span><p>Mika brought rigor without making the process rigid. The new system finally sounds and works like us.</p><footer><b>Rania Prasetyo</b><small>Product Director, Morrow</small></footer></blockquote><figure className="co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover" src="/themes/mono-portfolio/reviewer.jpg" alt="Rania Prasetyo, product director" /></figure><div className="mp-review-notes"><article><ThemeIcon name="heart" size={16} /><p>Every workshop gave our team a decision we could immediately use.</p><small>Aji · Kindred</small></article><article><ThemeIcon name="heart" size={16} /><p>The interface feels distinct without asking users to relearn familiar patterns.</p><small>Nadia · Orbit</small></article></div></div></section>

    <section className="mp-section mp-faq co-grid"><div><SectionTag>FAQ</SectionTag><h2>Before<br />we begin.</h2><p>A useful partnership starts with shared expectations. Here are the answers teams usually need first.</p><PortfolioButton href="#contact">Ask another question</PortfolioButton></div><div>{faqs.map(([question,answer],index)=><details key={question} open={index===0}><summary className="co-flex co-items-center co-justify-between">{question}<span>+</span></summary><p>{answer}</p></details>)}</div></section>

    <section className="mp-section mp-journal"><div className="mp-heading is-centered co-text-center"><SectionTag centered>Journal</SectionTag><h2>Ideas worth<br />sharing.</h2><p>Notes on product thinking, useful brands, collaboration, and designing work that lasts.</p></div><div className="mp-post-grid co-grid">{posts.map(([image,date,title])=><article className="co-transition co-duration-300 co-ease-out" key={title}><img className="co-w-full co-object-cover" src={`/themes/mono-portfolio/${image}`} alt="" /><div><small><ThemeIcon name="calendar" size={13} tone="lime" />{date}</small><h3>{title}</h3><a className="co-inline-flex co-items-center" href="#contact">Read note <ThemeIcon name="arrow-right" size={14} tone="lime" /></a></div></article>)}</div></section>

    <footer className="mp-footer" id="contact"><div className="mp-footer-cta co-flex co-items-center co-justify-between"><h2>Let&apos;s make<br />something useful.</h2><PortfolioButton href="mailto:hello@mono.example" light>Start a project</PortfolioButton></div><div className="mp-footer-main co-grid"><a className="mp-brand co-flex co-items-center" href="#top"><b>M.</b><span>Mono Portfolio<br /><small>Independent creative practice</small></span></a><div><b>Menu</b><a href="#about">About</a><a href="#work">Work</a><a href="#services">Services</a></div><div><b>Contact</b><a href="mailto:hello@mono.example">hello@mono.example</a><a href="#contact">Jakarta · worldwide</a><a href="#contact">+62 812 9000 1820</a></div><div><b>Elsewhere</b><a href="#contact">Instagram</a><a href="#contact">LinkedIn</a><a href="#contact">Behance</a></div></div><div className="mp-footer-bottom co-flex co-items-center co-justify-between"><span>© 2026 Coordiation. All rights reserved.</span><a className="co-inline-flex co-items-center" href="#top">Back to top <ThemeIcon name="arrow-to-top-right" size={14} tone="light" /></a></div></footer>
  </main>;
}

.mono-portfolio {
  --mp-ink: #0a0a0a;
  --mp-paper: #f2f0e9;
  --mp-lime: #c9ff2f;
  --mp-white: #fff;
  --mp-muted: #686862;
  --mp-line: rgba(10, 10, 10, .24);
  min-height: 100vh;
  background: var(--mp-paper);
  color: var(--mp-ink);
  font-family: Arial, Helvetica, sans-serif;
  font-size: 15px;
  line-height: 1.55;
}

.mono-portfolio *, .mono-portfolio *::before, .mono-portfolio *::after { box-sizing: border-box; }
.mono-portfolio h1, .mono-portfolio h2, .mono-portfolio h3, .mono-portfolio p, .mono-portfolio figure, .mono-portfolio blockquote { margin: 0; }
.mono-portfolio a { color: inherit; text-decoration: none; }
.mono-portfolio img { display: block; max-width: 100%; }
.mono-portfolio button, .mono-portfolio summary { font: inherit; }
.mono-portfolio .co-flex { display: flex; }
.mono-portfolio .co-inline-flex { display: inline-flex; }
.mono-portfolio .co-grid { display: grid; }
.mono-portfolio .co-items-center { align-items: center; }
.mono-portfolio .co-items-end { align-items: flex-end; }
.mono-portfolio .co-justify-center { justify-content: center; }
.mono-portfolio .co-justify-between { justify-content: space-between; }
.mono-portfolio .co-flex-col { flex-direction: column; }
.mono-portfolio .co-flex-wrap { flex-wrap: wrap; }
.mono-portfolio .co-relative { position: relative; }
.mono-portfolio .co-absolute { position: absolute; }
.mono-portfolio .co-overflow-hidden { overflow: hidden; }
.mono-portfolio .co-w-full { width: 100%; }
.mono-portfolio .co-h-full { height: 100%; }
.mono-portfolio .co-object-cover { object-fit: cover; }
.mono-portfolio .co-text-center { text-align: center; }
.mono-portfolio .co-transition { transition-property: color, background-color, border-color, transform, opacity; }
.mono-portfolio .co-duration-300 { transition-duration: 300ms; }
.mono-portfolio .co-ease-out { transition-timing-function: cubic-bezier(.16, 1, .3, 1); }

.mp-icon { display: inline-block; flex: 0 0 auto; object-fit: contain; }
.mp-icon-light { filter: brightness(0) invert(1); }
.mp-icon-lime { filter: brightness(0) saturate(100%) invert(98%) sepia(88%) saturate(1938%) hue-rotate(22deg) brightness(107%) contrast(101%); }

.mp-header {
  grid-template-columns: minmax(230px, .8fr) minmax(470px, 1.5fr) 210px;
  min-height: 82px;
  border-bottom: 1px solid var(--mp-line);
  background: var(--mp-paper);
}
.mp-brand { gap: 14px; min-height: 82px; padding: 0 28px; border-right: 1px solid var(--mp-line); }
.mp-brand > b { display: grid; width: 42px; height: 42px; place-items: center; background: var(--mp-ink); color: var(--mp-white); font-size: 21px; line-height: 1; }
.mp-brand > span { font-size: 13px; font-weight: 800; line-height: 1.12; text-transform: uppercase; }
.mp-brand small { color: var(--mp-muted); font-size: 10px; font-weight: 500; letter-spacing: .04em; text-transform: none; }
.mp-header nav { height: 100%; gap: clamp(22px, 3vw, 50px); border-right: 1px solid var(--mp-line); }
.mp-header nav a { position: relative; font-size: 12px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.mp-header nav a::after { position: absolute; right: 0; bottom: -8px; left: 0; height: 2px; background: var(--mp-lime); content: ""; transform: scaleX(0); transform-origin: left; transition: transform .3s ease; }
.mp-header nav a:hover::after { transform: scaleX(1); }
.mp-header-cta { align-self: stretch; padding: 0 28px; background: var(--mp-ink); color: var(--mp-white) !important; font-size: 12px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.mp-menu { display: none; }

.mp-section, .mp-hero { width: min(1180px, calc(100% - 48px)); margin-inline: auto; }
.mp-hero { grid-template-columns: .9fr 1.1fr; gap: clamp(50px, 8vw, 120px); min-height: 700px; padding: 80px 0; }
.mp-tag { gap: 9px; margin-bottom: 24px !important; color: var(--mp-ink); font-size: 11px; font-weight: 900; letter-spacing: .15em; text-transform: uppercase; }
.mp-tag > span { width: 8px; height: 8px; background: var(--mp-lime); border: 1px solid var(--mp-ink); }
.mp-tag.is-centered { justify-content: center; }
.mp-hero h1 { max-width: 650px; font-size: clamp(50px, 6vw, 88px); font-weight: 900; letter-spacing: -.065em; line-height: .88; }
.mp-hero h1 em { font-style: normal; -webkit-text-stroke: 1.5px var(--mp-ink); color: transparent; }
.mp-hero-copy > p { max-width: 540px; margin-top: 30px; color: var(--mp-muted); font-size: 17px; }
.mp-actions { gap: 24px; margin-top: 36px; }
.mp-actions > a:last-child { display: inline-flex; align-items: center; gap: 8px; border-bottom: 1px solid var(--mp-ink); font-size: 12px; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; }
.mp-button { min-width: 154px; min-height: 50px; gap: 24px; padding: 0 18px; border: 1px solid var(--mp-ink); background: var(--mp-ink); color: var(--mp-white) !important; font-size: 11px; font-weight: 900; letter-spacing: .09em; text-transform: uppercase; }
.mp-button:hover { background: var(--mp-lime); color: var(--mp-ink) !important; transform: translateY(-2px); }
.mp-button:hover .mp-icon { filter: none; }
.mp-button.is-light { background: var(--mp-lime); color: var(--mp-ink) !important; }
.mp-button.is-light:hover { background: var(--mp-white); }

.mp-hero-board { grid-template-columns: 1.35fr .9fr; grid-template-rows: 122px 180px 130px 52px; min-height: 500px; border: 1px solid var(--mp-ink); background: var(--mp-white); box-shadow: 15px 15px 0 rgba(10,10,10,.09); }
.mp-hero-board > figure { grid-row: 1 / 4; border-right: 1px solid var(--mp-ink); }
.mp-location, .mp-social, .mp-count { padding: 20px; }
.mp-location { display: grid; grid-template-columns: 26px 1fr; align-content: center; background: var(--mp-lime); border-bottom: 1px solid var(--mp-ink); }
.mp-location small { grid-column: 2; color: rgba(10,10,10,.64); font-size: 11px; }
.mp-social { background: var(--mp-ink); color: var(--mp-white); border-bottom: 1px solid var(--mp-paper); }
.mp-social > small { display: block; margin-bottom: 12px; color: #aaa; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
.mp-social > div { gap: 9px; }
.mp-social a { display: grid; width: 34px; height: 34px; place-items: center; border: 1px solid #555; font-size: 10px; }
.mp-social a:hover { border-color: var(--mp-lime); color: var(--mp-lime); }
.mp-count { display: flex; flex-direction: column; justify-content: center; }
.mp-count strong { font-size: 40px; line-height: 1; }
.mp-count span { font-weight: 800; }
.mp-count small { display: flex; gap: 6px; align-items: center; margin-top: 8px; color: var(--mp-muted); font-size: 10px; }
.mp-skills { grid-column: 1 / 3; gap: 20px; padding: 0 18px; border-top: 1px solid var(--mp-ink); overflow: hidden; white-space: nowrap; }
.mp-skills b { font-size: 10px; letter-spacing: .1em; text-transform: uppercase; }
.mp-skills span { padding-left: 20px; border-left: 1px solid var(--mp-line); font-size: 11px; }

.mp-marquee { overflow: hidden; border-block: 1px solid var(--mp-ink); background: var(--mp-ink); color: var(--mp-white); }
.mp-marquee > div { width: max-content; }
.mp-marquee span { gap: 24px; padding: 18px 24px; font-size: clamp(23px, 3vw, 41px); font-weight: 900; letter-spacing: -.04em; line-height: 1; text-transform: uppercase; white-space: nowrap; }
.mp-marquee i { width: 9px; height: 9px; background: var(--mp-lime); }

.mp-section { padding: 112px 0; }
.mp-section h2, .mp-trust h2, .mp-footer h2 { font-size: clamp(42px, 5vw, 72px); font-weight: 900; letter-spacing: -.06em; line-height: .94; }
.mp-hero h1, .mp-section h2, .mp-trust h2, .mp-footer h2, .mp-feature-project h3, .mp-post-grid h3 { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
.mp-about { grid-template-columns: .95fr .75fr 1fr; gap: 54px; border-bottom: 1px solid var(--mp-line); }
.mp-about-copy > p { max-width: 380px; margin: 26px 0 34px; color: var(--mp-muted); font-size: 16px; }
.mp-about > figure { min-height: 540px; border: 1px solid var(--mp-ink); }
.mp-tools > b { display: block; margin-bottom: 22px; font-size: 11px; letter-spacing: .15em; text-transform: uppercase; }
.mp-tools article { grid-template-columns: 40px 1fr; gap: 16px; padding: 18px 0; border-top: 1px solid var(--mp-line); }
.mp-tools article:last-child { border-bottom: 1px solid var(--mp-line); }
.mp-tools h3 { font-size: 15px; }
.mp-tools p { color: var(--mp-muted); font-size: 12px; }

.mp-heading { gap: 50px; margin-bottom: 56px; }
.mp-heading > p { max-width: 450px; color: var(--mp-muted); font-size: 16px; }
.mp-heading.is-centered { max-width: 720px; margin-inline: auto; }
.mp-heading.is-centered > p { margin: 20px auto 0; }
.mp-work-grid { grid-template-columns: 1.55fr .85fr; gap: 28px; }
.mp-feature-project { min-height: 490px; background: var(--mp-ink); }
.mp-feature-project::after { position: absolute; inset: 0; background: linear-gradient(transparent 35%, rgba(0,0,0,.78)); content: ""; }
.mp-feature-project > img { transition-duration: .7s !important; }
.mp-feature-project:hover > img { transform: scale(1.05); }
.mp-feature-project > div { right: 0; bottom: 0; left: 0; z-index: 1; padding: 28px; color: var(--mp-white); }
.mp-feature-project small { font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
.mp-feature-project h3 { max-width: 500px; margin: 8px 0 18px; font-size: 28px; line-height: 1.05; }
.mp-project-list > a:not(.mp-button) { min-height: 72px; padding: 0 18px; border: 1px solid var(--mp-line); border-bottom: 0; font-size: 14px; font-weight: 800; }
.mp-project-list > a:not(.mp-button):hover { padding-left: 26px; background: var(--mp-lime); }
.mp-project-list > a:last-of-type { border-bottom: 1px solid var(--mp-line); }
.mp-project-list .mp-button { margin-top: 24px; }

.mp-services { padding-top: 60px; }
.mp-service-grid { grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--mp-ink); border-left: 1px solid var(--mp-ink); }
.mp-service { min-height: 300px; padding: 24px; border-right: 1px solid var(--mp-ink); border-bottom: 1px solid var(--mp-ink); }
.mp-service > span { display: block; margin-bottom: 50px; font-size: 11px; }
.mp-service h3 { margin: 28px 0 8px; font-size: 19px; }
.mp-service p { max-width: 300px; color: var(--mp-muted); font-size: 13px; }
.mp-service a { position: absolute; right: 0; bottom: 0; width: 45px; height: 45px; background: var(--mp-lime); opacity: 0; transform: translate(8px,8px); }
.mp-service:hover { background: var(--mp-white); }
.mp-service:hover a { opacity: 1; transform: translate(0); }

.mp-trust { grid-template-columns: .8fr 1.2fr; gap: clamp(50px, 8vw, 120px); padding: 110px max(24px, calc((100vw - 1180px)/2)); background: var(--mp-ink); color: var(--mp-white); }
.mp-trust .mp-tag { color: var(--mp-white); }
.mp-trust-points { grid-template-columns: repeat(2, 1fr); }
.mp-trust-points article { min-height: 235px; padding: 25px; border: 1px solid #383838; }
.mp-trust-points article > span { float: right; color: var(--mp-lime); font-size: 11px; }
.mp-trust-points h3 { margin: 35px 0 9px; font-size: 18px; }
.mp-trust-points p { color: #aaa; font-size: 13px; }
.mp-trust-points figure { grid-row: span 2; min-height: 470px; }

.mp-plan-grid { grid-template-columns: repeat(3, 1fr); border: 1px solid var(--mp-ink); }
.mp-plan { min-height: 430px; padding: 30px; border-right: 1px solid var(--mp-ink); }
.mp-plan:last-child { border-right: 0; }
.mp-plan.is-featured { position: relative; background: var(--mp-ink); color: var(--mp-white); }
.mp-plan > small { position: absolute; top: 0; right: 0; padding: 8px 12px; background: var(--mp-lime); color: var(--mp-ink); font-size: 10px; font-weight: 900; text-transform: uppercase; }
.mp-plan h3 { font-size: 21px; }
.mp-plan > p { margin: 18px 0 30px; color: var(--mp-muted); }
.mp-plan.is-featured > p { color: #aaa; }
.mp-plan strong { font-size: 46px; letter-spacing: -.05em; }
.mp-plan strong span { font-size: 11px; font-weight: 500; letter-spacing: 0; }
.mp-plan ul { margin: 30px 0; padding: 0; list-style: none; }
.mp-plan li { gap: 10px; margin: 9px 0; font-size: 13px; }
.mp-plan .mp-button { margin-top: auto; }

.mp-review-grid { grid-template-columns: .7fr 1.05fr .7fr .8fr; min-height: 440px; border: 1px solid var(--mp-ink); }
.mp-review-grid > * { border-right: 1px solid var(--mp-ink); }
.mp-review-grid > *:last-child { border-right: 0; }
.mp-review-grid > aside, .mp-review-grid blockquote, .mp-review-notes article { padding: 25px; }
.mp-review-grid aside > strong { font-size: 58px; line-height: 1; }
.mp-review-grid aside > strong small { font-size: 16px; }
.mp-review-grid aside > p { margin: 18px 0; color: var(--mp-muted); font-size: 13px; }
.mp-review-grid aside > div { margin-bottom: 35px; letter-spacing: .18em; }
.mp-review-grid blockquote { display: flex; flex-direction: column; background: var(--mp-ink); color: var(--mp-white); }
.mp-review-grid blockquote > span { color: var(--mp-lime); font-size: 70px; line-height: .6; }
.mp-review-grid blockquote > p { margin-top: 30px; font-size: 21px; font-weight: 700; line-height: 1.3; }
.mp-review-grid blockquote footer { display: block; margin-top: auto; padding: 0; border: 0; background: transparent; color: inherit; font: inherit; }
.mp-review-grid blockquote footer b, .mp-review-grid blockquote footer small { display: block; }
.mp-review-grid blockquote footer small { color: #aaa; }
.mp-review-notes { display: grid; grid-template-rows: 1fr 1fr; }
.mp-review-notes article:first-child { border-bottom: 1px solid var(--mp-ink); }
.mp-review-notes p { margin: 18px 0; font-weight: 700; }
.mp-review-notes small { color: var(--mp-muted); }

.mp-faq { grid-template-columns: .75fr 1.25fr; gap: 100px; border-top: 1px solid var(--mp-line); }
.mp-faq > div:first-child > p:not(.mp-tag) { max-width: 380px; margin: 24px 0 32px; color: var(--mp-muted); }
.mp-faq details { border-top: 1px solid var(--mp-ink); }
.mp-faq details:last-child { border-bottom: 1px solid var(--mp-ink); }
.mp-faq summary { min-height: 68px; gap: 20px; cursor: pointer; font-weight: 800; list-style: none; }
.mp-faq summary::-webkit-details-marker { display: none; }
.mp-faq summary span { font-size: 22px; transition: transform .25s ease; }
.mp-faq details[open] summary span { transform: rotate(45deg); }
.mp-faq details p { max-width: 620px; padding: 0 45px 22px 0; color: var(--mp-muted); }

.mp-post-grid { grid-template-columns: repeat(3, 1fr); align-items: start; gap: 16px; }
.mp-post-grid article { display: grid; grid-template-rows: 220px auto; min-height: 0; overflow: hidden; background: var(--mp-ink); color: var(--mp-white); }
.mp-post-grid article:hover { transform: translateY(-8px); }
.mp-post-grid img { height: 220px; }
.mp-post-grid article > div { display: flex; min-height: 245px; padding: 23px; flex-direction: column; }
.mp-post-grid small { display: flex; align-items: center; gap: 8px; color: var(--mp-lime); font-size: 10px; text-transform: uppercase; }
.mp-post-grid h3 { min-height: 0; margin: 16px 0 26px; font-size: 21px; line-height: 1.25; }
.mp-post-grid a { gap: 8px; margin-top: auto; font-size: 11px; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; }

.mp-footer { display: block; width: 100%; margin: 0; padding: 0 max(24px, calc((100vw - 1180px)/2)); border: 0; background: var(--mp-ink); color: var(--mp-white); font: inherit; }
.mp-footer-cta { gap: 40px; padding: 80px 0 56px; border-bottom: 1px solid #333; }
.mp-footer-main { grid-template-columns: 1.4fr .55fr 1fr .6fr; gap: 45px; padding: 50px 0; }
.mp-footer .mp-brand { min-height: 0; padding: 0; border: 0; }
.mp-footer-main > div { display: flex; flex-direction: column; gap: 8px; }
.mp-footer-main > div > b { margin-bottom: 10px; color: var(--mp-lime); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
.mp-footer-main > div a { color: #aaa; font-size: 12px; }
.mp-footer-main > div a:hover { color: var(--mp-white); }
.mp-footer-bottom { min-height: 70px; border-top: 1px solid #333; color: #888; font-size: 11px; }
.mp-footer-bottom a { gap: 8px; color: var(--mp-white); }

@keyframes mp-marquee { to { transform: translateX(-50%); } }
@keyframes mp-pulse { 50% { opacity: .35; transform: scale(.72); } }
.mono-portfolio .co-animate-\[mp-marquee_24s_linear_infinite\] { animation: mp-marquee 24s linear infinite; }
.mono-portfolio .motion-safe\:co-animate-pulse { animation: mp-pulse 1.7s ease-in-out infinite; }

@media (max-width: 1050px) {
  .mp-header { grid-template-columns: 1fr 170px; }
  .mono-portfolio .mp-header nav { display: none; }
  .mp-header .mp-brand { border-right: 1px solid var(--mp-line); }
  .mono-portfolio .mp-header-cta { display: none; }
  .mp-menu { position: relative; display: block; height: 100%; }
  .mp-menu summary { display: grid; height: 100%; place-items: center; cursor: pointer; list-style: none; }
  .mp-menu summary::-webkit-details-marker { display: none; }
  .mp-menu > div { position: absolute; top: 82px; right: 0; z-index: 10; display: grid; width: min(300px, 90vw); border: 1px solid var(--mp-ink); background: var(--mp-paper); box-shadow: 8px 8px 0 var(--mp-lime); }
  .mp-menu > div a { padding: 15px 20px; border-bottom: 1px solid var(--mp-line); font-weight: 800; }
  .mp-hero { grid-template-columns: 1fr; }
  .mp-hero-copy { padding-top: 30px; }
  .mp-about { grid-template-columns: 1fr 1fr; }
  .mp-about-copy { grid-column: 1 / 3; }
  .mp-trust { grid-template-columns: 1fr; }
  .mp-review-grid { grid-template-columns: 1fr 1fr; }
  .mp-review-grid > * { min-height: 360px; border-bottom: 1px solid var(--mp-ink); }
  .mp-review-grid > *:nth-child(2) { border-right: 0; }
  .mp-footer-main { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 700px) {
  .mono-portfolio { font-size: 16px; }
  .mp-header { grid-template-columns: 1fr 74px; min-height: 72px; }
  .mp-brand { min-height: 72px; padding: 0 16px; }
  .mp-brand > b { width: 38px; height: 38px; }
  .mp-menu > div { top: 72px; }
  .mp-section, .mp-hero { width: min(100% - 32px, 1180px); }
  .mp-hero { min-height: auto; gap: 48px; padding: 64px 0; }
  .mp-hero h1 { font-size: clamp(48px, 15vw, 68px); }
  .mp-hero-board { grid-template-columns: 1fr; grid-template-rows: 430px auto auto auto auto; }
  .mp-hero-board > figure { grid-row: auto; border-right: 0; border-bottom: 1px solid var(--mp-ink); }
  .mp-skills { grid-column: auto; flex-wrap: wrap; min-height: 70px; padding-block: 12px; }
  .mp-section { padding: 80px 0; }
  .mp-about, .mp-work-grid, .mp-faq { grid-template-columns: 1fr; gap: 45px; }
  .mp-about-copy { grid-column: auto; }
  .mp-about > figure { min-height: 470px; }
  .mp-heading { display: block; }
  .mp-heading > p { margin-top: 20px; }
  .mp-service-grid, .mp-plan-grid, .mp-post-grid { grid-template-columns: 1fr; }
  .mp-post-grid article { grid-template-rows: 210px auto; }
  .mp-post-grid img { height: 210px; }
  .mp-post-grid article > div { min-height: 220px; }
  .mp-plan { border-right: 0; border-bottom: 1px solid var(--mp-ink); }
  .mp-plan:last-child { border-bottom: 0; }
  .mp-trust { padding-block: 80px; }
  .mp-trust-points { grid-template-columns: 1fr; }
  .mp-trust-points figure { grid-row: auto; min-height: 360px; }
  .mp-review-grid { grid-template-columns: 1fr; }
  .mp-review-grid > * { border-right: 0; }
  .mp-review-grid > figure { min-height: 430px; }
  .mp-footer-cta { align-items: flex-start; flex-direction: column; }
  .mp-footer-main { grid-template-columns: 1fr 1fr; }
  .mp-footer-main > .mp-brand { grid-column: 1 / 3; margin-bottom: 16px; }
  .mp-footer-bottom { align-items: flex-start; flex-direction: column; justify-content: center; gap: 8px; }
}

@media (max-width: 390px) {
  .mp-brand small { display: none; }
  .mp-actions { align-items: stretch; flex-direction: column; }
  .mp-actions .mp-button { width: 100%; }
  .mp-hero-board { grid-template-rows: 360px auto auto auto auto; }
  .mp-section h2, .mp-trust h2, .mp-footer h2 { font-size: 39px; }
  .mp-footer-main { grid-template-columns: 1fr; }
  .mp-footer-main > .mp-brand { grid-column: auto; }
}

@media (prefers-reduced-motion: reduce) {
  .mono-portfolio *, .mono-portfolio *::before, .mono-portfolio *::after { scroll-behavior: auto !important; animation: none !important; transition-duration: .01ms !important; }
}

import type { ReactNode } from "react";
import ThemeIcon, { type ThemeIconName } from "./ThemeIcon";

export function PortfolioButton({ href, children, light = false }: { href: string; children: ReactNode; light?: boolean }) {
  return <a className={`mp-button co-inline-flex co-items-center co-justify-between co-transition co-duration-300 co-ease-out motion-reduce:co-animate-none${light ? " is-light" : ""}`} href={href}>{children}<ThemeIcon name="arrow-right" size={15} tone={light ? "dark" : "light"} /></a>;
}

export function SectionTag({ children, centered = false }: { children: ReactNode; centered?: boolean }) {
  return <p className={`mp-tag co-inline-flex co-items-center${centered ? " is-centered" : ""}`}><span className="motion-safe:co-animate-pulse motion-reduce:co-animate-none" />{children}</p>;
}

export function ServiceCell({ number, icon, title, copy }: { number: string; icon: ThemeIconName; title: string; copy: string }) {
  return <article className="mp-service co-relative co-transition co-duration-300 co-ease-out"><span>{number}</span><ThemeIcon name={icon} size={42} /><h3>{title}</h3><p>{copy}</p><a className="co-inline-flex co-items-center co-justify-center" href="#contact" aria-label={`Explore ${title}`}><ThemeIcon name="arrow-to-top-right" size={15} /></a></article>;
}

export function PlanCard({ name, price, featured = false }: { name: string; price: string; featured?: boolean }) {
  return <article className={`mp-plan co-flex co-flex-col${featured ? " is-featured" : ""}`}>{featured && <small>Most selected</small>}<h3>{name}</h3><p>For focused teams ready to turn positioning into a clear, useful digital product.</p><strong>{price}<span>/project</span></strong><ul>{["Strategy workshop", "Responsive interface", "Design system", "Handover support"].map(item=><li className="co-flex co-items-center" key={item}><ThemeIcon name="check-circle" size={14} />{item}</li>)}</ul><PortfolioButton href="#contact" light={featured}>Choose plan</PortfolioButton></article>;
}
